pub fn genericDump(type_name: ?[]const u8, ptr: *anyopaque, total_ref_count: usize, map: *std.AutoHashMapUnmanaged(TrackedRef.Id, TrackedRef)) void {
        const tracked_refs = map.count();
        const untracked_refs = (total_ref_count - tracked_refs);
        _ = bun.Output.prettyError("<blue>{s}{s}{x} has ", .{ ((type_name) orelse ("")), (if ((type_name != null)) "@" else ""), (blk: {
        break :blk @intFromPtr(ptr);

}) });
        if ((tracked_refs > 0)) {
            _ = bun.Output.prettyError("{d} tracked{s}", .{ tracked_refs, (if ((untracked_refs > 0)) ", " else "") });
        }
        if ((untracked_refs > 0)) {
            _ = bun.Output.prettyError("{d} untracked refs<r>\n", .{ untracked_refs });
        } else {
            _ = bun.Output.prettyError("refs<r>\n", &.{});
        }
        var i: usize = 0;
        _ = &i;
        var it = map.iterator();
        _ = &it;
        while (it.next()) |entry| {
            _ = bun.Output.prettyError("<b>RefPtr acquired at:<r>\n", &.{});
            _ = bun.crash_handler.dumpStackTrace(entry.value_ptr.acquired_at.trace(), AllocationScope.trace_limits);
            i = (i + 1);
            if ((i >= 3)) {
                _ = bun.Output.prettyError("  {d} omitted ...\n", .{ (map.count() - i) });
                break;
            }
        }
}

